package application.adapters.persistence.jpa.entities;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * JPA persistence entity for Shipment (inferred class). An order may have
 * several shipments, one per dispatching warehouse.
 */
@Entity
@Table(name = "shipments")
@Getter
@Setter
@NoArgsConstructor
public class ShipmentJpaEntity {

    /** Shipment.identifier (decision D2), generated by the adapter. */
    @Id
    @Column(name = "identifier", nullable = false, length = 60)
    private String identifier;

    @Column(name = "order_identifier", nullable = false, length = 60)
    private String orderIdentifier;

    @Column(name = "warehouse_identifier", length = 60)
    private String warehouseIdentifier;

    @Column(name = "logistics_operator_identifier", length = 60)
    private String logisticsOperatorIdentifier;

    /** ShipmentStatus enum name. */
    @Column(name = "status", length = 20)
    private String status;
}
